NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Hosea'

CHAPTERS = {
    1: {
        1: 'Gospodova beseda, ki je prišla Beeríjevemu sinu Ozeju v dneh Uzíjaha, Jotáma, Aháza in Ezekíja, Judovih kraljev in v dneh Joáševega sina Jerobeáma, Izraelovega kralja.',
        2: 'Začetek Gospodove besede po Ozeju. Gospod je Ozeju rekel: »Pojdi, vzemi si ženo vlačugarstev in otroke vlačugarstev, kajti dežela je zagrešila veliko vlačugarstvo, odhajajoč od Gospoda.«',
        3: 'Torej je odšel in vzel Diblájimovo hčer Gómero, ki je spočela in mu rodila sina.',
        4: 'Gospod mu je rekel: »Njegovo ime kliči Jezreél, kajti le še malo in jaz bom maščeval kri Jezreéla na Jehújevi hiši in povzročil bom, da bo prenehalo kraljestvo Izraelove hiše.',
        5: 'Na ta dan se bo zgodilo, da bom Izraelov lok zlomil v dolini Jezreél.«',
        6: '§ Ponovno je spočela in rodila hčer. Bog mu je rekel: »Njeno ime kliči Nepomiloščena, kajti ne bom več imel milosti nad Izraelovo hišo, temveč jih bom popolnoma odvedel stran.',
        7: 'Toda imel bom usmiljenje nad Judovo hišo in rešil jih bom po Gospodu, njihovem Bogu in ne bom jih rešil z lokom, niti z mečem, niti z bitko, [niti] s konji, niti s konjeniki.«',
        8: 'Torej, ko je odstavila Nepomiloščeno, je spočela in rodila sina.',
        9: 'Potem je Bog rekel: »Njegovo ime kliči Ne-moje-ljudstvo, kajti vi niste moje ljudstvo in jaz ne bom vaš Bog.«',
        10: 'Vendar bo število Izraelovih otrok kakor morskega peska, ki ne more biti izmerjen niti preštet in zgodilo se bo, da jim bo na kraju, kjer jim je bilo rečeno: ›Vi niste moje ljudstvo,‹ tam jim bo rečeno: › Vi ste sinovi živega Boga.‹',
        11: 'Potem bodo Judovi otroci in Izraelovi otroci zbrani skupaj in določili si bodo eno glavo in prišli bodo gor iz dežele, kajti velik bo Jezreélov dan.‹',
    },
    2: {
        1: 'Svojim bratom recite: ›Moje ljudstvo‹ in svojim sestram: ›Pomiloščena.‹',
        2: 'Pravdajte se s svojo materjo, pravdajte, kajti ona ni moja žena niti jaz nisem njen soprog. Naj torej odloži svoja vlačugarstva iz svojega pogleda in svoja zakonolomstva izmed svojih prsi,',
        3: 'da je ne bom slekel do golega in jo postavil kakor na dan, ko je bila rojena in jo naredil kakor divjino in jo postavil kakor suho deželo in jo pogubil z žejo.',
        4: 'Ne bom se usmilil njenih otrok, kajti oni so otroci vlačugarstev.',
        5: 'Kajti njihova mati je igrala pocestnico. Ta, ki jih je spočela, je storila sramotno, kajti rekla je: ›Hodila bom za svojimi ljubimci, ki mi dajejo moj kruh in mojo vodo, mojo volno in moj lan, moje olje in mojo pijačo.‹',
        6: 'Zatorej glej, tvojo pot bom ogradil s trnjem in naredil zid, da ne bo našla svojih steza.',
        7: 'Sledila bo za svojimi ljubimci, toda ne bo jih dohitela in iskala jih bo, toda ne bo jih našla. Tedaj bo rekla: ›Šla bom in se vrnila k svojemu prvemu soprogu, kajti takrat je bilo z menoj bolje kakor sedaj.‹',
        8: 'Kajti ni vedela, da sem ji jaz dajal njeno žito, vino, olje in množil njeno srebro in zlato, ki so ga pripravili za Báala.',
        9: 'Zatorej se bom vrnil in odvzel svoje žito ob njegovem času in svoje vino v njegovem obdobju in nazaj bom dobil svojo volno in svoj lan, izročen, da pokrije njeno nagoto.',
        10: 'Sedaj bom odkril njeno nespodobnost pred očmi njenih ljubimcev in nihče je ne bo rešil iz moje roke.',
        11: 'Prav tako bom vsemu njenemu veselju povzročil, da bo prenehalo, njenim prazničnim dnevom, njenim mlajem, njenim šabatom in vsem njenim slovesnim praznikom.',
        12: 'Uničil bom njene trte in njena figova drevesa, o katerih je rekla: ›To so moje nagrade, ki so mi jih dajali moji ljubimci.‹ Jaz pa jih bom naredil za gozd in živali polja jih bodo jedle.',
        13: 'Na njej bom obiskal dneve Báalov, na katere jim je zažigala kadilo in se krasila s svojimi uhani in svojimi dragocenostmi in hodila za svojimi ljubimci, mene pa pozabila,« govori Gospod.',
        14: '»Zatorej glej, jaz jo bom privabil in jo pripeljal v divjino in ji tolažilno prigovarjal.',
        15: 'Jaz ji bom od tam dal njene vinograde in dolino Ahór za vrata upanja in ona bo tam prepevala kakor v dneh svoje mladosti in kakor na dan, ko je prišla gor iz egiptovske dežele.',
        16: 'In zgodilo se bo tisti dan,« govori Gospod, » da me boš klicala: ›Ishi‹ in ne boš me več klicala: ›Báali.‹',
        17: 'Kajti odstranil bom imena Báalov iz njenih ust in po njihovem imenu se jih ne bodo več spominjali.',
        18: '§ Na ta dan bom zanje sklenil zavezo s poljskimi živalmi, s perjadjo neba in s plazečimi stvarmi zemlje. Prelomil bom lok, meč in bitko z zemlje in storil jim bom, da se varno zleknejo.',
        19: 'In zaročil te bom k sebi za vedno. Da, zaročil te bom k sebi v pravičnosti, v sodbi, v ljubeči skrbnosti in v milostih.',
        20: 'Zaročil te bom k sebi, celo v zvestobi in spoznala boš Gospoda.',
        21: 'Zgodilo se bo na tisti dan; uslišal bom,« govori Gospod, »uslišal bom nebo in to bo uslišalo zemljo',
        22: 'in zemlja bo uslišala žito in vino in olje in ti bodo uslišali Jezreéla.',
        23: 'Posejal si jo bom na zemlji in usmilil se bom nje, ki ni dosegla usmiljenja in rekel bom tistim, ki niso bili moje ljudstvo: ›Vi ste moje ljudstvo.‹ In oni bodo rekli: › Ti si moj Bog.‹«',
    },
    3: {
        1: 'Potem mi je Gospod rekel: »Pojdi že, ljubi žensko, ljubljeno od njenega prijatelja, vendar zakonolomko, glede na Gospodovo ljubezen do Izraelovih otrok, ki gledajo k drugim bogovom in ljubijo flaškone vina.«',
        2: 'Tako sem si jo kupil za petnajst koščkov srebra in za tovor ječmena in pol tovora ječmena.',
        3: 'Rekel sem ji: »Mnogo dni boš čakala name. Ne boš igrala pocestnice in ne boš za drugega moškega; tako bom tudi jaz nate.«',
        4: '§ Kajti Izraelovi otroci bodo mnogo dni ostali brez kralja, brez princa, brez klavne daritve, brez podobe, brez efóda in brez družinskega malika.',
        5: '§ Potem se bodo Izraelovi otroci vrnili in iskali Gospoda, svojega Boga in Davida, svojega kralja in bali se bodo Gospoda in njegove dobrote v zadnjih dneh.',
    },
    4: {
        1: 'Poslušajte Gospodovo besedo, vi Izraelovi otroci, kajti Gospod ima polemiko s prebivalci dežele, zato ker tam ni resnice niti usmiljenja niti spoznanja Boga v deželi.',
        2: 'S priseganjem, laganjem, ubijanjem, krajo in zagrešitvami zakonolomstva so izbruhnili in kri se dotika krvi.',
        3: 'Zato bo dežela žalovala in kdor v njej prebiva bo opešal, z živalmi polja in s perjadjo neba. Da, tudi ribe morja bodo odvzete.',
        4: 'Vendarle naj se noben človek ne prepira niti naj ne graja drugega, kajti tvoje ljudstvo je kakor tisti, ki se prepirajo z duhovnikom.',
        5: '»Zato boš padel podnevi in tudi prerok bo padel s teboj ponoči in jaz bom uničil tvojo mater.',
        6: 'Moje ljudstvo je uničeno zaradi pomanjkanja spoznanja. Ker si zavrnil spoznanje, bom tudi jaz zavrnil tebe, da mi ne boš duhovnik. Ker si pozabil postavo svojega Boga, bom tudi jaz pozabil tvoje otroke.',
        7: 'Kakor so bili pomnoženi, tako so grešili zoper mene, zato bom njihovo slavo spremenil v sramoto.',
        8: '§ Jedo greh mojega ljudstva in svoja srca naravnavajo na svojo krivičnost.',
        9: 'In tam bo, kakršno ljudstvo, takšen duhovnik, in jaz jih bom kaznoval za njihove poti in jim nagradil njihova početja.',
        10: 'Kajti jedli bodo, pa ne bodo imeli dovolj, zagrešili bodo vlačugarstvo, pa se ne bodo pomnožili, ker so opustili, da bi bili pozorni na Gospoda.',
        11: 'Vlačugarstvo, vino in novo vino jemljejo srce.',
        12: 'Moje ljudstvo sprašuje za nasvet pri svojih kladah in njihova palica jim napoveduje, kajti duh vlačugarstev jim je povzročil, da blodijo in odšli so se vlačugat proč izpred svojega Boga.',
        13: 'Žrtvujejo na vrhovih gora in kadilo zažigajo na hribih, pod hrasti, topoli in bresti, ker je njihova senca dobra. Zatorej bodo vaše hčere zagrešile vlačugarstvo in vaše snahe bodo zagrešile zakonolomstvo.',
        14: 'Ne bom kaznoval vaših hčera, ko bodo zagrešile vlačuganje niti vaših snah, kadar bodo zagrešile zakonolomstvo, kajti oni sami so oddvojeni z vlačugami in žrtvujejo s pocestnicami. Zatorej bo ljudstvo, ki ne razume, padlo.',
        15: 'Čeprav ti, Izrael, igraš pocestnico, naj vendar Juda ne greši. Ne prihajajte v Gilgál, niti ne hodite gor v Bet Aven, niti ne prisegajte: › Gospod živi.‹',
        16: 'Kajti Izrael drsi nazaj kakor nazaj zdrknjena telica. Sedaj jih bo Gospod pasel kakor jagnje na velikem kraju.',
        17: 'Efrájim je pridružen malikom, pusti ga samega.',
        18: '§ Njihova pijača je kisla. Spet in spet zagrešujejo vlačugarstvo. Njegovi vladarji ljubijo s sramoto: ›Dajajte.‹',
        19: 'Veter je [Izraela] zvezal v svoje peruti in osramočeni bodo zaradi svojih [klavnih] daritev.',
    },
    5: {
        1: 'Poslušajte to, oh duhovniki in pazljivo prisluhnite, vi, Izraelova hiša in nagnite uho, oh kraljeva hiša, kajti sodba je zoper vas, ker ste bili zanka na Micpi in mreža, razpeta na [gori] Tabor.',
        2: '§ Puntarji so prodorni, da naredijo pokol, čeprav sem bil jaz oštevalec njih vseh.',
        3: 'Poznam Efrájima in Izrael ni skrit pred menoj, kajti sedaj, oh Efrájim, zagrešuješ vlačugarstvo in Izrael je omadeževan.«',
        4: 'Svojih ravnanj ne bodo snovali, da bi se obrnili k svojemu Bogu, kajti duh vlačugarstev je v njihovi sredi in niso spoznali Gospoda.',
        5: 'Izraelov ponos pričuje v njegov obraz, zatorej bosta Izrael in Efrájim padla v svoji krivičnosti. Tudi Juda bo padel z njima.',
        6: 'Šli bodo s svojimi tropi in s svojimi čredami, da bi iskali Gospoda, toda ne bodo ga našli. On se je oddaljil od njih.',
        7: 'Zahrbtno so ravnali zoper Gospoda, kajti zaplodili so tuje otroke. Sedaj jih bo požrl mesec z njihovimi deleži.',
        8: 'Zatrobite na kornét v Gíbei in na trobento v Rami, kričite glasno pri Bet Avenu, za teboj, oh Benjamin.',
        9: 'Efrájim bo zapuščen na dan oštevanja. Med Izraelovimi rodovi sem dal spoznati tisto, kar zagotovo bo.',
        10: 'Judovi princi so bili kakor tisti, ki odstranjujejo mejo, zatorej bom nanje izlil svoj bes kakor vodo.',
        11: 'Efrájim je zatiran in razklan na sodbi, zato ker je voljan hodil za [človeško] zapovedjo.',
        12: '»Zato bom Efrájimu kakor molj, Judovi hiši pa kakor gniloba.',
        13: 'Ko je Efrájim videl svojo slabost in Juda videl svojo rano, takrat je šel Efrájim k Asircu in poslal h kralju Jarebu in vendar vas on ni mogel ozdraviti niti ozdraviti vaše rane.',
        14: 'Kajti jaz bom Efrájimu kakor lev in kakor mlad lev Judovi hiši. Jaz, celó jaz, bom raztrgal in odšel proč, jaz bom odnesel in nihče ga ne bo rešil.',
        15: 'Šel bom in se vrnil na svoj kraj, dokler ne bodo priznali svojega prestopka in iskali mojega obraza. V svoji stiski me bodo zgodaj iskali.«',
    },
    6: {
        1: 'Pridite in vrnimo se h Gospodu, kajti on je raztrgal in on nas bo ozdravil. Udaril je in nas bo obvezal.',
        2: 'Po dveh dneh nas bo oživil, v tretjem dnevu nas bo dvignil in živeli bomo v njegovem pogledu.',
        3: 'Takrat bomo vedeli ali še naprej sledimo, da bi spoznali Gospoda; njegov izhod je pripravljen kakor jutro in prišel bo k nam kakor dež, kakor pozni in prvi dež na zemljo.',
        4: '»Oh Efrájim, kaj naj ti storim? Oh Juda, kaj naj ti storim? Kajti vaša dobrota je kakor jutranji oblak in kakor zgodnja rosa odide proč.',
        5: 'Zatorej sem jih obtesaval po prerokih, moril sem jih z besedami iz svojih ust. Tvoje sodbe so kakor svetloba, ki gre naprej.',
        6: 'Kajti želel sem usmiljenja in ne klavne daritve, in spoznanja Boga bolj kakor žgalne daritve.',
        7: 'Toda podobni so ljudem, ki so prestopili zavezo. Tam so zoper mene ravnali zahrbtno.',
        8: 'Gileád je mesto tistih, ki počno krivičnost in je oskrunjeno s krvjo.',
        9: 'Kakor krdela roparjev prežijo na človeka, tako skupina duhovnikov mori po poti z odobravanjem, kajti zagrešujejo nespodobnost.',
        10: 'Videl sem strašno stvar v Izraelovi hiši. Tam je vlačugarstvo Efrájima, Izrael je omadeževan.',
        11: 'Prav tako, oh Juda, on je zate pripravil žetev, ko vrnem ujetništvo svojega ljudstva.',
    },
    7: {
        1: 'Ko sem hotel ozdraviti Izraela, takrat je bila odkrita krivičnost Efrájima in zlobnost Samarije, kajti zagrešili so neresnico. In tat vstopa in krdelo roparjev pleni zunaj.',
        2: 'V svojih srcih pa ne preudarijo, da se spominjam vse njihove zlobnosti. Sedaj so jih njihova lastna dejanja obkrožila; pred mojim obrazom so.',
        3: 'Kralja razveseljujejo s svojo zlobnostjo in prince s svojimi lažmi.',
        4: 'Vsi so zakonolomci, kakor peč, ki jo segreje pek, ki preneha kuriti, potem ko je pregnetel testo, dokler to ni vzhajano.',
        5: '§ Na dan našega kralja so ga princi naredili bolnega z vinskimi mehovi; svojo roko podaja s posmehljivci.',
        6: '§ Kajti svoje srce so pripravili kakor peč, medtem ko prežijo v zasedi. Njihov pek spi vso noč; zjutraj ta gori kakor plameneč ogenj.',
        7: 'Vsi so vroči kakor peč in požrli so svoje sodnike; vsi njihovi kralji so padli; tam ni nobenega izmed njih, ki kliče k meni.',
        8: 'Efrájim se je pomešal med ljudstvo, Efrájim je neobrnjen kolač.',
        9: 'Tujci so požrli njegovo moč, on pa tega ne spoznava. Da, sivi lasje so tu in tam na njem, vendar ne spoznava.',
        10: 'Izraelov ponos pričuje v njegov obraz, oni pa se ne vrnejo h Gospodu, svojemu Bogu niti ga zaradi vsega tega ne iščejo.',
        11: 'Tudi Efrájim je podoben neumni golobici brez srca; kličejo k Egiptu, hodijo v Asirijo.',
        12: 'Ko bodo šli, bom nadnje razširil svojo mrežo. Sklatil jih bom dol kakor perjad neba, kaznoval jih bom, kakor je slišala njihova skupnost.',
        13: 'Gorje jim! Kajti zbežali so od mene. Naj jim bo namenjeno uničenje! Ker so se prekršili zoper mene. Čeprav sem jih odkupil, so oni kljub temu zoper mene govorili laži.',
        14: 'In niso klicali k meni s svojim srcem, ko so tulili na svojih posteljah; zbrali so se zaradi žita in vina in se uprli zoper mene.',
        15: 'Čeprav sem utrdil in okrepil njihove lakte, so zoper mene še vedno domišljali vragolijo.',
        16: 'Vračajo se, toda ne k Najvišjemu; so kot varljiv lok; njihovi princi bodo padli pod mečem zaradi besa njihovega jezika. To bo v njihov posmeh v egiptovski deželi.',
    },
    8: {
        1: 'Nastavi šofar k svojim ustom. Prišel bo kakor orel zoper Gospodovo hišo, zato ker so prekršili mojo zavezo in se prekršili zoper mojo postavo.',
        2: 'Izrael bo klical k meni: ›Moj Bog, mi te poznamo.‹',
        3: 'Izrael je zavrgel stvar, ki je dobra; sovražnik ga bo zasledoval.',
        4: 'Nastavljali so si kralje, toda ne po meni. Nameščali so si prince, jaz pa tega nisem vedel. Iz svojega srebra in svojega zlata so si delali malike, da bi bili lahko iztrebljeni.',
        5: 'Tvoje tele, oh Samarija, te je zavrglo. Moja jeza se je vnela zoper njih. Kako dolgo bo, preden se bodo dokopali do nedolžnosti?',
        6: 'Kajti tudi to je bilo iz Izraela; delavec ga je naredil, zato to ni Bog, temveč bo tele iz Samarije zlomljeno na koščke.',
        7: 'Kajti sejali so veter, želi bodo pa vihar. Ta nima stebla, brst ne obrodi moke. Če bo tako, da obrodi, ga bodo pogoltnili tujci.',
        8: 'Izrael je požrt; sedaj bodo med pogani kakor posoda, v kateri ni zadovoljstva.',
        9: 'Kajti šli so gor v Asirijo, osamljen divji osel sam zase. Efrájim si je najel ljubimce.',
        10: 'Da, čeprav so najemali med narodi, jih bom sedaj zbral in bodo malce žalovali zaradi bremena kralja princev.',
        11: 'Ker je Efrájim naredil mnogo oltarjev za greh, bodo oltarji njemu v greh.',
        12: 'Njemu sem napisal velike stvari iz svoje postave, vendar so bile štete kakor čudna stvar.«',
        13: 'Žrtvujejo meso za klavno daritev mojih daritev in ga jedo, toda Gospod jih ne sprejema. Sedaj se bo spomnil njihove krivičnosti in obiskal njihove grehe; vrnili se bodo v Egipt.',
        14: '»Kajti Izrael je pozabil svojega Stvarnika in zgradil templje in Juda je pomnožil utrjena mesta, toda na njegova mesta bom poslal ogenj in ta bo požrl njegove palače.',
    },
    9: {
        1: 'Ne veseli se, oh Izrael, zaradi radosti kakor drugo ljudstvo, kajti šel si vlačugarsko od svojega Boga, ljubil si nagrado na vsakem žitnem mlatišču.',
        2: 'Mlatišče in vinska stiskalnica jih ne bosta hranila in novo vino se bo pokvarilo v njej.',
        3: 'Ne bodo prebivali v Gospodovi deželi, temveč se bo Efrájim vrnil v Egipt in v Asiriji bodo jedli nečiste stvari.',
        4: 'Ne bodo več darovali vinskih daritev Gospodu niti mu ne bodo ugajale. Njihove klavne daritve jim bodo kakor kruh žalovalcev. Vsi, ki bodo jedli od njih, bodo oskrunjeni, kajti njihov kruh, za njihovo dušo, ne bo prišel v Gospodovo hišo.',
        5: 'Kaj boste storili na slovesen dan in na dan Gospodovega praznika?',
        6: 'Kajti glej, odšli so zaradi uničenja. Egipt jih bo zbral, Memfis jih bo pokopal. Prijetne kraje za njihovo srebro bodo imele koprive v lasti, trnje bo v njihovih šotorskih svetiščih.',
        7: 'Prišli so dnevi obiskanja, prišli so dnevi povračila, Izrael bo to vedel. Prerok je bedak, duhoven človek je zmešan zaradi množice tvoje krivičnosti in velikega sovraštva.',
        8: 'Efrájimov stražar je bil z mojim Bogom, toda prerok je ptičarjeva zanka na vseh njegovih poteh in sovraštvo v hiši njegovega Boga.',
        9: 'Globoko so se izpridili, kakor v dneh Gíbee, zato se bo spomnil njihove krivičnosti, obiskal bo njihove grehe.',
        10: '»Izraela sem našel podobnega trtam v divjini. Vaše očete sem videl kakor prvi sad na figovem drevesu ob njegovem prvem času, toda odšli so k Báal Peórju in se oddvojili v to sramoto in njihove ogabnosti so bile glede na to, kar so ljubili.',
        11: 'Glede Efrájima, njihova slava bo odletela proč kakor ptica, od poroda in od maternice in od spočetja.',
        12: 'Čeprav bodo vzredili svoje otroke, jih bom vendar oropal, da tam noben človek ne bo ostal. Da, gorje tudi tistim, ko odidem od njih!',
        13: 'Efrájim je, kakor sem videl Tir, zasajen na prijetnem kraju, toda Efrájim bo svoje otroke privedel k morilcu.«',
        14: 'Daj jim, oh Gospod. Kaj hočeš dati? Daj jim maternico, ki splavlja in suhe prsi.',
        15: '»Vsa njihova zlobnost je v Gilgálu, kajti tam sem jih zasovražil. Zaradi zlobnosti njihovih početij jih bom pognal iz svoje hiše. Ne bom jih več ljubil. Vsi njihovi princi so puntarji.',
        16: 'Efrájim je udarjen, njihova korenina je posušena, nobenega sadu ne bodo obrodili. Da, čeprav bodo obrodili, bom vendar ubil celó ljubljeni sad njihove maternice.«',
        17: 'Moj Bog jih bo zavrgel, ker mu niso prisluhnili in oni bodo postopači med narodi.',
    },
    10: {
        1: 'Izrael je prazna trta, sebi prinaša sad. Glede na množico svojega sadu je množil oltarje. Glede na dobroto njegove dežele so naredili čedne podobe.',
        2: 'Njihovo srce je razdeljeno, sedaj bodo najdeni pomanjkljivi. Zrušil bo njihove oltarje, oplenil njihove podobe.',
        3: 'Kajti sedaj bodo rekli: ›Nimamo kralja, ker se nismo bali Gospoda. Kaj naj bi nam torej storil kralj?‹',
        4: 'Govorili so besede, lažno prisegali pri sklepanju zaveze. Tako sodba poganja kakor pikasti mišjak na brazdah polja.',
        5: 'Prebivalci Samarije bodo trepetali zaradi telet Bet Avena, kajti ljudstvo le-teh bo nad tem žalovalo in duhovniki le-teh, ki so se ob tem veselili, [bodo trepetali] zaradi slave [bogov zlatih telet], zato ker je ta odšla od njih.',
        6: 'Prav tako bo le-to odneseno v Asirijo za darilo kralju Jarebu. Efrájim bo prejel sramoto in Izrael se bo sramoval svojega lastnega nasveta.',
        7: '§ Glede Samarije, njen kralj je odsekan kakor pena na vodi.',
        8: 'Prav tako bodo uničeni visoki kraji Avena, Izraelov greh. Trnje in osat bosta pognala na njihovih oltarjih in goram bodo rekli: »Pokrijte nas« in hribom: »Padite na nas.«',
        9: 'Oh Izrael, grešil si od dni Gíbee. Tam so stali, bitka v Gíbei zoper otroke krivičnosti jih ni dosegla.',
        10: 'Po moji želji je, da naj jih kaznujem, in ljudstvo se bo zbralo zoper njih, ko se bodo zvezali v svojih dveh brazdah.',
        11: 'Efrájim je kakor telica, ki je poučena in rada mendra žito, toda jaz sem šel čez njen lepi vrat. Efrájima bom pripravil, da jaha, Juda bo oral, Jakob pa bo branal.',
        12: 'Sejte si v pravičnosti, žanjite v usmiljenju, pobranajte svoja neposejana tla, kajti čas je, da iščete Gospoda, dokler ne pride in na vas dežuje pravičnost.',
        13: 'Orali ste zlobnost, želi ste krivičnost, jedli ste sad laži, ker ste zaupali v svojo pot in v množico svojih mogočnih mož.',
        14: 'Zato bo med tvojim ljudstvom vstal nemir in vse tvoje trdnjave bodo oplenjene, kakor je na dan bitke Šalmán oplenil Bet Arbeél. Mati je bila raztreščena na koščke na svojih otrocih.',
        15: 'Tako vam bo storil Betel zaradi vaše velike zlobnosti. Zjutraj bo Izraelov kralj popolnoma iztrebljen.',
    },
    11: {
        1: 'Ko je bil Izrael otrok, takrat sem ga ljubil in svojega sina poklical iz Egipta.',
        2: 'Kakor so jih [preroki] klicali, tako so odhajali od njih. Žrtvovali so Báalom in rezanim podobam zažigali kadilo.',
        3: '§ Tudi Efrájima sem učil hoditi in jih držal za njihove lakte, toda niso spoznali, da sem jih jaz ozdravil.',
        4: '§ Pritegoval sem jih s človeškimi vrvicami, z vezmi ljubezni in bil sem jim kakor tisti, ki snamejo jarem z njihovih čeljusti in jaz sem jim dajal hrano.',
        5: 'Ne bo se vrnil v egiptovsko deželo, temveč bo Asirec njegov kralj, ker so zavrnili, da bi se vrnili.',
        6: '§ Meč bo ostajal na njegovih mestih in použije njegove mladike in jih požre zaradi njihovih lastnih nasvetov.',
        7: '§ Moje ljudstvo je nagnjeno k odpadu od mene. Čeprav so jih klicali k Najvišjemu, ga sploh nihče ni hotel povišati.',
        8: 'Kako naj bi se ti odrekel, Efrájim? Kako naj bi te izročil, Izrael? Kako naj bi te naredil kakor Admo? Kako naj bi te postavil kakor Cebojím? Moje srce je spremenjeno znotraj mene, poleg tega so se moja kesanja razvnela.',
        9: 'Ne bom izvršil okrutnosti svoje jeze, ne bom se vrnil, da uničim Efrájima, kajti jaz sem Bog in ne človek, Sveti v tvoji sredi in ne bom vstopil v mesto.«',
        10: '§ Hodili bodo za Gospodom, rjovel bo kakor lev. Ko bo zarjovel, potem bodo otroci pritrepetali od zahoda.',
        11: 'Pritrepetali bodo kakor ptica iz Egipta in kakor golobica iz asirske dežele in postavil jih bom v njihove hiše,« govori Gospod.',
        12: '»Efrájim me obdaja z lažmi in Izraelova hiša s prevaro, toda Juda še vlada z Bogom in je zvest s svetimi.',
    },
    12: {
        1: 'Efrájim se hrani z vetrom in sledi vzhodnemu vetru, dnevno povečuje laži in opustošenje, sklepa zavezo z Asirci in olje nosi v Egipt.',
        2: 'Prav tako ima Gospod polemiko z Judom in kaznoval bo Jakoba glede na njegove poti; poplačal mu bo glede na njegova dejanja.',
        3: 'V maternici je svojega brata prijel za peto in s svojo močjo je imel moč z Bogom.',
        4: 'Da, imel je moč nad angelom in je prevladal. Jokal je in ponižno prosil k njemu. Našel ga je v Betelu in tam je [Bog] govoril z nami;',
        5: 'celo Gospod Bog nad bojevniki; Gospod je njegov spomenik.',
        6: 'Zatorej se obrni k svojemu Bogu, ohranjaj usmiljenje in sodbo in nenehno čakaj na svojega Boga.',
        7: 'On je trgovec, v njegovi roki so tehtnice prevare, rad zatira.',
        8: 'Efrájim je rekel: »Vendar sem postal bogat, pridobil sem si imetje, v vseh mojih naporih ne bodo našli v meni nobene krivičnosti, da bi bila greh.«',
        9: '»Jaz pa, ki sem Gospod, tvoj Bog, od egiptovske dežele, te bom vendarle prisilil, da prebivaš v šotorih kakor v dneh slovesnega praznika.',
        10: 'Prav tako sem govoril po prerokih in množil videnja ter po služenju prerokov uporabljal prilike.',
        11: 'Ali je v Gileádu krivičnost? Oni so zagotovo ničevost. V Gilgálu žrtvujejo bikce. Da, njihovi oltarji so kakor kupi na brazdah polj.',
        12: '§ Jakob je zbežal v sirsko deželo in Izrael je služil za ženo in za ženo je varoval ovce.',
        13: 'In po preroku je Gospod Izraela privedel iz Egipta in po preroku je bil obvarovan.',
        14: 'Efrájim ga je silno grenko izzival k jezi, zatorej bo njegovo kri pustil nad njim in njegovo grajo bo njegov Gospod povrnil k njemu.',
    },
    13: {
        1: 'Ko je Efrájim trepetajoč govoril, se je povišal v Izraelu, toda ko se je pohujšal z Báalom, je umrl.',
        2: '§ In sedaj bolj in bolj grešijo in iz svojega srebra so si naredili ulite podobe in malike, glede na svoje lastno razumevanje. Vsi ti so delo rokodelcev, o njih pravijo: ›Naj možje, ki žrtvujejo, poljubijo teleta.‹',
        3: 'Zatorej bodo kakor jutranji oblak in kakor zgodnja rosa, ki izginja, kakor pleve, ki je z vrtinčastim vetrom odpihnjeno iz mlatišča in kakor dim iz dimnika.',
        4: 'In vendar jaz sem Gospod, tvoj Bog, od egiptovske dežele in razen mene ne boš poznal nobenega boga, kajti poleg mene ni rešitelja.',
        5: 'Poznal sem te v divjini, v deželi velike suše.',
        6: 'Glede na njihov pašnik, tako so bili nasičeni; nasičeni so bili in njihovo srce je bilo povzdignjeno, zato so me pozabili.',
        7: 'Zatorej jim bom kakor lev, kakor leopard ob poti jih bom opazoval.',
        8: 'Srečal jih bom kakor medvedka, ki je oropana svojih mladičev in raztrgal bom opno njihovega srca in tam jih bom požrl kakor lev. Divja žival jih bo trgala.',
        9: '§ Oh Izrael, uničeval si samega sebe, toda v meni je tvoja pomoč.',
        10: '§ Jaz bom tvoj kralj. Kje je katerikoli drug, ki te lahko reši v vseh tvojih mestih? In tvoji sodniki, o katerih praviš: ›Daj mi kralja in prince?‹',
        11: 'V svoji jezi sem ti dal kralja in v svojem besu sem ga vzel proč.',
        12: 'Krivičnost Efrájima je zvezana, njegov greh je skrit.',
        13: 'Bridkosti ženske v porodnih mukah bodo prišle nadenj. On je nespameten sin, kajti ne bi smel dolgo ostati v odprtini rojevanja otrok.',
        14: '§ Odkupil jih bom pred oblastjo groba; odkupil jih bom pred smrtjo. ›Oh smrt, jaz bom tvoje kuge;‹ ›Oh grob, jaz bom tvoje uničenje.‹ Kesanje bo skrito mojim očem.',
        15: 'Čeprav bi bil rodoviten med svojimi brati, bo prišel vzhodni veter, veter od Gospoda bo prišel gor iz divjine in njegov izvir se bo posušil in njegov studenec bo osušen. Oplenil bo zaklad vseh prijetnih posod.',
        16: 'Samarija bo postala zapuščena, kajti uprla se je zoper svojega Boga. Padli bodo pod mečem, njihovi otročiči bodo razbiti na koščke in njihove nosečnice bodo razparane.',
    },
    14: {
        1: 'Oh Izrael, vrni se h Gospodu, svojemu Bogu, kajti padel si zaradi svoje krivičnosti.',
        2: 'S seboj vzemite besede in se obrnite h Gospodu. Recite mu: ›Odvzemi proč vso krivičnost in nas milostljivo sprejmi, tako bomo povrnili teleta svojih ustnic.‹',
        3: 'Asúr nas ne bo rešil, ne bomo jahali na konjih niti delu naših rok ne bomo več rekli: › Vi ste naši bogovi,‹ kajti v tebi osiroteli najde usmiljenje.',
        4: 'Jaz bom ozdravil njihov odpad, velikodušno jih bom ljubil, kajti moja jeza se je odvrnila od njega.',
        5: 'Izraelu bom kakor rosa. Rasel bo kakor lilija in svoje korenine poganjal kakor Libanon.',
        6: 'Njegove mladike se bodo razširile in njegova lepota bo kakor oljka in njegov vonj kakor Libanon.',
        7: 'Tisti, ki prebivajo pod njegovo senco, se bodo vrnili; oživeli bodo kakor žito in rastli kakor trta. Njegova vonjava bo kakor libanonsko vino.',
        8: 'Efrájim bo rekel: ›Kaj imam še opraviti z maliki?‹ Slišal sem ga in ga opazil. Podoben sem zeleni cipresi. Od mene je najti tvoj sad.',
        9: 'Kdo je moder in bo razumel te stvari? Razsoden in jih bo spoznal? Kajti Gospodove poti so pravilne in pravični se bo ravnal po njih. Toda prestopniki bodo padli na njih.«',
    },
}
